import React, { useState } from 'react';
import { PROJECT_CATEGORIES, PROJECTS_LIST } from '../Data/mockData';
import { BookText, FileCode2, Presentation, HelpCircle } from 'lucide-react';

export default function ProjectsScreen({ type = 'B.Tech', onOpenEnquiry }) {
  const [selectedCat, setSelectedCat] = useState('Python');

  const badges = [
    { label: 'Abstract', icon: BookText },
    { label: 'Modules', icon: FileCode2 },
    { label: 'Documentation', icon: BookText },
    { label: 'Source Code', icon: FileCode2 },
    { label: 'PPT', icon: Presentation },
    { label: 'Demo', icon: Presentation },
    { label: 'Viva Support', icon: HelpCircle }
  ];

  const filtered = PROJECTS_LIST.filter((p) => {
    const matchDegree = p.degree === 'Both' || p.degree === type;
    const matchCat = selectedCat === 'All' || p.category === selectedCat;
    return matchDegree && matchCat;
  });

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12 space-y-12">
      <div className="text-center max-w-3xl mx-auto space-y-3">
        <h1 className="text-4xl sm:text-5xl font-extrabold text-white">
          {type} Projects Screen
        </h1>
        <p className="text-slate-400 text-sm sm:text-base">
          IEEE standard source code, architecture modules, documentation, and defense support for final semester students.
        </p>
      </div>

      {/* Category tabs */}
      <div className="flex flex-wrap items-center justify-center gap-2">
        {PROJECT_CATEGORIES.map((cat) => (
          <button
            key={cat}
            onClick={() => setSelectedCat(cat)}
            className={`px-4 py-2 rounded-xl text-xs font-semibold transition ${
              selectedCat === cat
                ? 'bg-violet-600 text-white shadow-md'
                : 'bg-slate-900 border border-slate-800 text-slate-300 hover:bg-slate-800'
            }`}
          >
            {cat}
          </button>
        ))}
      </div>

      {/* Detailed project item view with badges */}
      <div className="bg-slate-900/80 border border-slate-800 rounded-2xl p-6">
        <p className="text-xs uppercase tracking-wider text-slate-400 font-semibold text-center mb-4">
          All Project Packages Include Deliverables:
        </p>
        <div className="flex flex-wrap items-center justify-center gap-3">
          {badges.map((b, i) => (
            <span key={i} className="inline-flex items-center space-x-1.5 px-3 py-1.5 rounded-lg bg-slate-800 text-emerald-300 border border-slate-700 text-xs font-medium">
              <span>{b.label}</span>
            </span>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {filtered.map((proj) => (
          <div
            key={proj.id}
            className="bg-slate-900 border border-slate-800 rounded-3xl p-6 sm:p-8 flex flex-col justify-between space-y-6 shadow-xl"
          >
            <div className="space-y-3">
              <span className="text-xs font-bold px-3 py-1 rounded-full bg-violet-600/30 text-violet-300 border border-violet-500/30">
                {proj.category}
              </span>
              <h3 className="text-xl font-bold text-white">{proj.title}</h3>
              <p className="text-xs text-slate-400">
                Complete modular backend routes, responsive frontend views, database design, and research base paper.
              </p>
            </div>

            <div className="flex items-center justify-between pt-4 border-t border-slate-800">
              <button
                onClick={() => onOpenEnquiry(proj.title)}
                className="px-4 py-2.5 bg-slate-800 hover:bg-slate-700 text-slate-200 text-xs font-semibold rounded-xl border border-slate-700 transition"
              >
                View Projects
              </button>
              <button
                onClick={() => onOpenEnquiry(proj.title)}
                className="px-5 py-2.5 bg-gradient-to-r from-violet-600 to-indigo-600 hover:from-violet-500 hover:to-indigo-500 text-white text-xs font-bold rounded-xl shadow-md transition"
              >
                Request Project
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
